1	package warranty
2	
3	import (
4		"errors"
5		"math"
6		"testing"
7		"time"
8	)
9	
10	// 重复登记的保护：已登记的非空编号再次提交时一律报 ErrDuplicateID，
11	// 无论新条款是否合法；原产品的购买时刻、保修天数和除外集合完整保留，
12	// 资格判断、预留与历史依据都继续按第一次成功登记的条款执行。
13	
14	// checkProductTerms 校验取回的产品资料与首次登记的条款完全一致。
15	func checkProductTerms(t *testing.T, s *Store, id string, purchase time.Time, days int, codes ...string) {
16		t.Helper()
17		p, err := s.Product(id)
18		if err != nil {
19			t.Fatalf("product %q: %v", id, err)
20		}
21		if !p.PurchaseTime.Equal(purchase) {
22			t.Fatalf("product %q purchase time = %v, want %v", id, p.PurchaseTime, purchase)
23		}
24		if p.WarrantyDays != days {
25			t.Fatalf("product %q warranty days = %d, want %d", id, p.WarrantyDays, days)
26		}
27		if len(p.ExcludedCodes) != len(codes) {
28			t.Fatalf("product %q excluded codes = %v, want exactly %v", id, p.ExcludedCodes, codes)
29		}
30		for _, c := range codes {
31			if _, ok := p.ExcludedCodes[c]; !ok {
32				t.Fatalf("product %q excluded codes = %v, missing %q", id, p.ExcludedCodes, c)
33			}
34		}
35	}
36	
37	// 新条款与旧条款明显不同（购买时刻、保修天数、除外清单全部改变）时，
38	// 重复登记仍报 ErrDuplicateID，原记录三项条款完整保留，不是部分保留。
39	func TestDuplicateProductDifferentTermsKeepsOriginal(t *testing.T) {
40		s := NewStore()
41		if err := s.RegisterProduct("p1", t0, 30, []string{"FAULTX", "FAULTY"}); err != nil {
42			t.Fatalf("register product: %v", err)
43		}
44		// 三项条款全部不同的合法新提交。
45		err := s.RegisterProduct("p1", t0.Add(5*day), 300, []string{"FAULTZ"})
46		if !errors.Is(err, ErrDuplicateID) {
47			t.Fatalf("duplicate with different terms: got %v, want ErrDuplicateID", err)
48		}
49		// 原条款完整保留：购买时刻、天数、除外集合都不被新提交改动。
50		checkProductTerms(t, s, "p1", t0, 30, "FAULTX", "FAULTY")
51	}
52	
53	// 重复编号同时带有非法条款时，编号重复优先于参数校验：报 ErrDuplicateID
54	// 而不是 ErrInvalidParam，原记录不被清空或部分替换。
55	func TestDuplicateProductInvalidTermsStillDuplicate(t *testing.T) {
56		cases := []struct {
57			name     string
58			purchase time.Time
59			days     int
60			codes    []string
61		}{
62			{"zero days", t0, 0, nil},
63			{"negative days", t0, -5, nil},
64			{"unrepresentable expiry", t0, math.MaxInt, nil},
65			{"empty excluded code", t0, 10, []string{""}},
66			{"empty code among valid", t0, 10, []string{"FAULTZ", ""}},
67		}
68		for _, tc := range cases {
69			t.Run(tc.name, func(t *testing.T) {
70				s := NewStore()
71				if err := s.RegisterProduct("p1", t0, 30, []string{"FAULTX"}); err != nil {
72					t.Fatalf("register product: %v", err)
73				}
74				err := s.RegisterProduct("p1", tc.purchase, tc.days, tc.codes)
75				if !errors.Is(err, ErrDuplicateID) {
76					t.Fatalf("duplicate with invalid terms: got %v, want ErrDuplicateID", err)
77				}
78				if errors.Is(err, ErrInvalidParam) {
79					t.Fatalf("duplicate id must win over param validation, got %v", err)
80				}
81				checkProductTerms(t, s, "p1", t0, 30, "FAULTX")
82			})
83		}
84	}
85	
86	// 重复登记被拒绝后，资格继续按原购买时刻与原期限判断：按原条款仍在保的
87	// 请求不因新期限较短而被拒绝；按原条款已过保的请求不借较长的新期限重新
88	// 合格。原清单中的除外故障仍被拒绝，仅出现在新清单中的故障不构成除外。
89	// 直接查询资格与按请求查看资格依据都显示原保修条款。
90	func TestDuplicateRejectionKeepsOriginalEligibility(t *testing.T) {
91		s := NewStore()
92		if err := s.RegisterProduct("p1", t0, 30, []string{"FAULTX"}); err != nil {
93			t.Fatalf("register product: %v", err)
94		}
95		for _, r := range []struct{ id, fault string }{
96			{"rPlain", "FAULTY"},
97			{"rExcluded", "FAULTX"},
98			{"rNewOnly", "FAULTZ"},
99		} {
100			if err := s.SubmitRequest(r.id, "p1", r.fault); err != nil {
101				t.Fatalf("submit %s: %v", r.id, err)
102			}
103		}
104		// 较短的新期限（5 天）加一份不同的除外清单：登记被拒绝。
105		if err := s.RegisterProduct("p1", t0, 5, []string{"FAULTZ"}); !errors.Is(err, ErrDuplicateID) {
106			t.Fatalf("duplicate with shorter term: got %v, want ErrDuplicateID", err)
107		}
108	
109		// 第 10 天：按原 30 天期限仍在保，按新 5 天期限已过保。
110		at := t0.Add(10 * day)
111		e, err := s.Evaluate("rPlain", at)
112		if err != nil {
113			t.Fatalf("evaluate: %v", err)
114		}
115		if !e.Eligible {
116			t.Fatalf("still in warranty under original terms, got reasons %v", e.Reasons)
117		}
118		if e.WarrantyDays != 30 || !e.PurchaseTime.Equal(t0) || !e.WarrantyExpiry.Equal(t0.Add(30*day)) {
119			t.Fatalf("eligibility basis = (%v, %d, %v), want original (%v, 30, %v)",
120				e.PurchaseTime, e.WarrantyDays, e.WarrantyExpiry, t0, t0.Add(30*day))
121		}
122		// 原清单中的除外故障仍被拒绝。
123		e, err = s.Evaluate("rExcluded", at)
124		if err != nil {
125			t.Fatalf("evaluate: %v", err)
126		}
127		if e.Eligible || !containsReason(e.Reasons, ReasonFaultExcluded) {
128			t.Fatalf("original exclusion lost: %+v", e)
129		}
130		// 仅出现在新清单中的故障不能成为除外。
131		e, err = s.Evaluate("rNewOnly", at)
132		if err != nil {
133			t.Fatalf("evaluate: %v", err)
134		}
135		if !e.Eligible {
136			t.Fatalf("fault only in rejected new list must not exclude, got reasons %v", e.Reasons)
137		}
138	
139		// 较长的新期限（300 天）：登记同样被拒绝。
140		if err := s.RegisterProduct("p1", t0, 300, nil); !errors.Is(err, ErrDuplicateID) {
141			t.Fatalf("duplicate with longer term: got %v, want ErrDuplicateID", err)
142		}
143		// 第 40 天：按原 30 天期限已过保，不能借新期限重新合格。
144		later := t0.Add(40 * day)
145		e, err = s.Evaluate("rPlain", later)
146		if err != nil {
147			t.Fatalf("evaluate: %v", err)
148		}
149		if e.Eligible || !containsReason(e.Reasons, ReasonWarrantyExpired) {
150			t.Fatalf("expired under original terms must stay ineligible, got %+v", e)
151		}
152		if e.WarrantyDays != 30 || !e.WarrantyExpiry.Equal(t0.Add(30*day)) {
153			t.Fatalf("eligibility basis changed: %+v", e)
154		}
155	
156		// 按请求查看资格依据：同样显示原保修条款与对应拒绝原因。
157		view, err := s.RequestView("rPlain", later)
158		if err != nil {
159			t.Fatalf("request view: %v", err)
160		}
161		ve := view.Eligibility
162		if ve.Eligible || !containsReason(ve.Reasons, ReasonWarrantyExpired) {
163			t.Fatalf("view eligibility = %+v, want expired under original terms", ve)
164		}
165		if ve.WarrantyDays != 30 || !ve.PurchaseTime.Equal(t0) || !ve.WarrantyExpiry.Equal(t0.Add(30*day)) {
166			t.Fatalf("view basis = (%v, %d, %v), want original terms",
167				ve.PurchaseTime, ve.WarrantyDays, ve.WarrantyExpiry)
168		}
169		view, err = s.RequestView("rExcluded", at)
170		if err != nil {
171			t.Fatalf("request view: %v", err)
172		}
173		if view.Eligibility.Eligible || !containsReason(view.Eligibility.Reasons, ReasonFaultExcluded) {
174			t.Fatalf("view for excluded fault = %+v", view.Eligibility)
175		}
176	}
177	
178	// 备件预留同样只认原条款：按原条款在保且未命中除外的请求，在库存足够、
179	// 承诺到期时刻晚于当前时刻时仍可预留；按原条款不合格的请求仍返回
180	// ErrIneligible，不生成承诺、不增加库存占用。重复登记失败不改动已有承诺
181	// 与已有预留历史中的资格依据。
182	func TestDuplicateRejectionKeepsReserveBehavior(t *testing.T) {
183		s := NewStore()
184		if err := s.RegisterProduct("p1", t0, 30, []string{"FAULTX"}); err != nil {
185			t.Fatalf("register product: %v", err)
186		}
187		if err := s.RegisterPart("part1", 10); err != nil {
188			t.Fatalf("register part: %v", err)
189		}
190		if err := s.SubmitRequest("rOK", "p1", "FAULTY"); err != nil {
191			t.Fatalf("submit: %v", err)
192		}
193		if err := s.SubmitRequest("rBad", "p1", "FAULTX"); err != nil {
194			t.Fatalf("submit: %v", err)
195		}
196		// 重复登记失败前已有一笔成功预留。
197		if _, err := s.Reserve("c1", "rOK", "part1", 4, expiryOK, nowOK); err != nil {
198			t.Fatalf("reserve c1: %v", err)
199		}
200		// 重复登记失败：新期限更短、除外清单不同。
201		if err := s.RegisterProduct("p1", t0, 5, []string{"FAULTY"}); !errors.Is(err, ErrDuplicateID) {
202			t.Fatalf("duplicate: got %v, want ErrDuplicateID", err)
203		}
204	
205		// 按原条款在保的请求（即使故障代码出现在新清单中）仍可预留。
206		if _, err := s.Reserve("c2", "rOK", "part1", 4, expiryOK, nowOK); err != nil {
207			t.Fatalf("reserve after rejected duplicate: %v", err)
208		}
209		// 按原条款命中除外的请求仍不合格：不生成承诺、不增加占用。
210		if _, err := s.Reserve("c3", "rBad", "part1", 1, expiryOK, nowOK); !errors.Is(err, ErrIneligible) {
211			t.Fatalf("reserve for excluded fault: got %v, want ErrIneligible", err)
212		}
213		if _, err := s.Commitment("c3"); !errors.Is(err, ErrNotFound) {
214			t.Fatalf("rejected reserve must not create a commitment, got %v", err)
215		}
216		st, err := s.PartStatus("part1", nowOK)
217		if err != nil {
218			t.Fatalf("part status: %v", err)
219		}
220		if st.ActiveOccupied != 8 || st.Committable != 2 || st.PhysicalRemaining != 10 {
221			t.Fatalf("stock = phys %d occupied %d committable %d, want 10/8/2",
222				st.PhysicalRemaining, st.ActiveOccupied, st.Committable)
223		}
224	
225		// 已有承诺不被重复登记失败改动。
226		c1, err := s.Commitment("c1")
227		if err != nil {
228			t.Fatalf("commitment c1: %v", err)
229		}
230		if c1.Quantity != 4 || c1.Used != 0 || c1.Canceled || c1.Expired {
231			t.Fatalf("existing commitment changed: %+v", c1)
232		}
233	
